from pipeline_io import *
m=read()
prompts=[
'Shot 1, 0–5 seconds: Use the first and last supplied images as opening and ending anchors. One continuous five-second shot. The man watches the table and walks counterclockwise, viewed from above, from the near long side around to the right short side, touching nothing. At exactly 3 seconds into the shot, the entire blue tissue pack including its protruding tissue disappears instantaneously from the unobstructed tabletop. The wooden cup stays empty at its fixed position. End with the man at the right short side and the pack absent. Gently track the elevated camera right, keeping the pack location and cup visible throughout the change. No sliding, morphing, fading, handling, occlusion tricks or internal cuts. Natural movement; no text or watermark.',
'Shot 2, 5–10 seconds: Use the first and last supplied images as opening and ending anchors. One continuous five-second shot. The man watches the table and continues counterclockwise, viewed from above, from the right short side around to the opposite long side, touching nothing. At exactly 3 seconds into this shot (8 seconds overall), a white porcelain cup containing dark tea appears instantaneously at the empty tabletop center. The wooden cup remains empty at its fixed position near the right end. End with both cups visible and the man at the opposite long side within reach of both. Gently move the elevated diagonal camera toward the far-right corner, keeping the tabletop center and wooden cup unobstructed at the instant of appearance. No sliding, morphing, fading, handling, occlusion tricks or internal cuts. Tissue pack stays absent. Natural movement; no text or watermark.',
'Shot 3, 10–15 seconds: Use the first and last supplied images as opening and ending anchors. One continuous five-second shot. During the first second, the man briefly turns his head toward the window and back to the table; keep him and the tabletop in frame. At exactly 2 seconds into this shot (12 seconds overall), with his hands away and both cups clearly visible, the cups instantaneously exchange positions: the empty wooden cup moves from the right-hand tabletop position to the center, and the tea-filled porcelain cup moves from the center to that vacated right-hand position. Preserve each cup’s material and contents. Only after the exchange, during seconds 2–5, he reaches for the porcelain cup at its new position, picks it up and drinks. End with that cup at his lips and the empty wooden cup at the center. Use gentle continuous elevated camera movement with minimal displacement, retaining both cup positions in frame. Tissue pack stays absent. No sliding, morphing, fading, handling or occlusion to cause the exchange; no internal cuts. Natural movement; no text or watermark.'
]
for s,pr in zip(m['shots'],prompts):P.joinpath(s['prompt_path']).write_text(pr+'\n')
m['shots'][2]['camera_motion']='Gentle continuous elevated near-center camera movement with minimal endpoint displacement, retaining B and C.'
for f in m['shots'][2]['frames'].values():f['camera']=m['shots'][2]['camera_motion']
m['assumptions'].append('Scene dimensions standardized to 1672x940, approximately 16:9, following built-in output; only one-pixel dimension repairs applied. Shot 3 uses minimal camera displacement; continuous motion is retained in video prompt.')
save(m)
